const issueInvoice = `-- name: IssueInvoice :execrows
UPDATE billing.invoice
SET status = 'issued', issued_by = $1, issued_at = $2,
    subtotal_minor = $3, discount_minor = $4,
    tax_minor = $5, total_minor = $6,
    discounts = $7, liability = $8,
    updated_at = $9, row_version = $10
WHERE tenant_id = $11 AND invoice_id = $12
  AND row_version = $13 AND status = 'draft'
`

type IssueInvoiceParams struct {
	IssuedBy        string
	IssuedAt        pgtype.Timestamptz
	SubtotalMinor   int64
	DiscountMinor   int64
	TaxMinor        int64
	TotalMinor      int64
	Discounts       []byte
	Liability       []byte
	UpdatedAt       pgtype.Timestamptz
	RowVersion      int64
	TenantID        uuid.UUID
	InvoiceID       uuid.UUID
	ExpectedVersion int64
}

// Guarded on the document still being a draft, so an invoice cannot be issued
// twice and cannot be issued after it has been superseded.
func (q *Queries) IssueInvoice(ctx context.Context, arg IssueInvoiceParams) (int64, error) {
	result, err := q.db.Exec(ctx, issueInvoice,
		arg.IssuedBy,
		arg.IssuedAt,
		arg.SubtotalMinor,
		arg.DiscountMinor,
		arg.TaxMinor,
		arg.TotalMinor,
		arg.Discounts,
		arg.Liability,
		arg.UpdatedAt,
		arg.RowVersion,
		arg.TenantID,
		arg.InvoiceID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

