const supersedeInvoice = `-- name: SupersedeInvoice :execrows
UPDATE billing.invoice
SET status = 'superseded', superseded_by = $1,
    updated_at = $2, row_version = $3
WHERE tenant_id = $4 AND invoice_id = $5
  AND row_version = $6
  AND kind IN ('estimate', 'interim')
  AND status IN ('draft', 'issued')
`

type SupersedeInvoiceParams struct {
	SupersededBy    pgtype.UUID
	UpdatedAt       pgtype.Timestamptz
	RowVersion      int64
	TenantID        uuid.UUID
	InvoiceID       uuid.UUID
	ExpectedVersion int64
}

// The only update an unissued document takes, and it applies to estimates and
// interim bills alone. There is deliberately no statement here that edits an
// issued invoice's totals or lines (SRS-BIL-010).
func (q *Queries) SupersedeInvoice(ctx context.Context, arg SupersedeInvoiceParams) (int64, error) {
	result, err := q.db.Exec(ctx, supersedeInvoice,
		arg.SupersededBy,
		arg.UpdatedAt,
		arg.RowVersion,
		arg.TenantID,
		arg.InvoiceID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

